"use strict";(globalThis.webpackChunkdocusaurus_temp=globalThis.webpackChunkdocusaurus_temp||[]).push([[4995],{4414(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>h});var n=a(7962),i=a(4848),s=a(8453);const r={title:"DevOps Is a Culture, Not a Team: What I've Learned Building at Scale",date:new Date("2026-04-26T00:00:00.000Z"),authors:["austin"],tags:["devops","sre","platform-engineering","kubernetes","cloud-computing","leadership"],description:"After 20 years running infrastructure at scale, here's what DevOps actually means \u2014 and why the most common implementation is an anti-pattern."},o=void 0,l={authorsImageUrls:[void 0]},h=[{value:"DevOps Is a Culture, Not a Team",id:"devops-is-a-culture-not-a-team",level:2},{value:"Platform Team: The Operationalized Version of DevOps at Scale",id:"platform-team-the-operationalized-version-of-devops-at-scale",level:2},{value:"The Ops Lifecycle: More Than Provisioning and Deploying",id:"the-ops-lifecycle-more-than-provisioning-and-deploying",level:2},{value:"IaC: Not Just Terraform, But a Mindset Shift",id:"iac-not-just-terraform-but-a-mindset-shift",level:2},{value:"CI/CD: What Good Actually Looks Like",id:"cicd-what-good-actually-looks-like",level:2},{value:"SLO/SLI: Turning Reliability Into a Currency",id:"slosli-turning-reliability-into-a-currency",level:2},{value:"High Scalability: Where DevOps Value Compounds",id:"high-scalability-where-devops-value-compounds",level:2},{value:"The AI Factor: DevOps as the Foundation for AI-Native Development",id:"the-ai-factor-devops-as-the-foundation-for-ai-native-development",level:2}];function d(e){const t={a:"a",code:"code",em:"em",h2:"h2",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:'Every organization that has gone through a "DevOps transformation" in the last decade has a story. Most of those stories end the same way: they hired a DevOps team, bought a set of tools, and then wondered why things didn\'t meaningfully change.'}),"\n",(0,i.jsx)(t.p,{children:"I've been building and running infrastructure at scale for 20 years \u2014 from private cloud on OpenStack at a large-scale e-commerce platform to managing 200+ Kubernetes clusters, 50,000 nodes, and 5,000+ applications. If there's one thing I've learned, it's that the most common implementation of DevOps is actually an anti-pattern."}),"\n",(0,i.jsx)(t.p,{children:"Let me explain what I mean."}),"\n",(0,i.jsx)(t.h2,{id:"devops-is-a-culture-not-a-team",children:"DevOps Is a Culture, Not a Team"}),"\n",(0,i.jsxs)(t.p,{children:["The first and most important thing to understand about DevOps is that it is a ",(0,i.jsx)(t.strong,{children:"cultural movement"}),", not a tool, a team, or a job title."]}),"\n",(0,i.jsx)(t.p,{children:"DevOps was born in 2009 out of a simple frustration: \"dev ships, ops runs\" creates systemic accidents. When the team that builds a service doesn't run it, they build it differently \u2014 less observably, with less concern for operational burden, with less skin in the game when 3am pages fire. The solution isn't tooling. The solution is ownership."}),"\n",(0,i.jsxs)(t.p,{children:["The core mental model is: ",(0,i.jsx)(t.strong,{children:'"you build it, you run it."'})," Teams own their services in production end-to-end. That changes everything about how software gets built."]}),"\n",(0,i.jsx)(t.p,{children:'The classic anti-pattern is creating a "DevOps team." At a surface level, this seems reasonable \u2014 put some experienced engineers in a room, give them the title, and let them drive the transformation. But what you\'ve actually done is recreate the original dev-vs-ops silo as a new gatekeeper. The DevOps team becomes the bottleneck, the org breathes a sigh of relief at having "done DevOps," and the culture doesn\'t change at all.'}),"\n",(0,i.jsxs)(t.p,{children:["The CALMS framework captures the full scope: ",(0,i.jsx)(t.strong,{children:"Culture, Automation, Lean, Measurement, Sharing."})," Most organizations focus on Automation (which is important) and skip Culture and Measurement (which are harder). That's why most DevOps transformations fail \u2014 not because the tools are wrong, but because the work that matters most isn't about tools."]}),"\n",(0,i.jsx)(t.h2,{id:"platform-team-the-operationalized-version-of-devops-at-scale",children:"Platform Team: The Operationalized Version of DevOps at Scale"}),"\n",(0,i.jsxs)(t.p,{children:["In ",(0,i.jsx)(t.a,{href:"https://austinxyz.github.io/blogs/blog/2026/03/16/platform-engineer-vs-ops-engineer",children:"a previous post"}),", I wrote about the difference between ops thinking and platform thinking. Platform Engineering is where DevOps becomes operationalized at scale."]}),"\n",(0,i.jsx)(t.p,{children:"At small scale \u2014 under 50 engineers \u2014 every team can do DevOps from scratch. Everyone knows each other, context is shared, incidents are rare. You can get by without formal DevOps investment."}),"\n",(0,i.jsx)(t.p,{children:'But at larger scale, the "every team does DevOps from scratch" approach breaks down fast. Each team is reinventing CI/CD, building their own observability stack, figuring out their own on-call process, and doing all of it slightly differently. The cognitive load multiplies across the organization. Engineers burn out on infrastructure concerns instead of building product.'}),"\n",(0,i.jsxs)(t.p,{children:["That's where Platform Engineering comes in. A Platform team builds the ",(0,i.jsx)(t.strong,{children:"paved path"})," \u2014 a curated, opinionated set of internal tools that other teams consume as a product. CI/CD that just works. Terraform modules that encode your organization's security and cost policies. Observability out of the box. On-call runbooks that don't require each team to rediscover what APF misconfiguration looks like at 2am."]}),"\n",(0,i.jsx)(t.p,{children:"Critical point: the platform team is not doing application ops. They're running the platform itself \u2014 the K8s clusters, the CI/CD system, the observability stack \u2014 and treating other engineering teams as their customers. Their metric isn't uptime; it's the productivity and autonomy of the teams they serve. Developer experience is the NPS score."}),"\n",(0,i.jsx)(t.h2,{id:"the-ops-lifecycle-more-than-provisioning-and-deploying",children:"The Ops Lifecycle: More Than Provisioning and Deploying"}),"\n",(0,i.jsx)(t.p,{children:"When people describe Ops work, they usually reach for the visible tools: Terraform for provisioning, CI/CD for deployment, monitoring for observability. That's a useful shorthand, but it misses where the real complexity lives."}),"\n",(0,i.jsx)(t.p,{children:"The full service lifecycle looks like this:"}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:"Design \u2192 Provision \u2192 Deploy \u2192 Operate \u2192 Evolve \u2192 Retire\n"})}),"\n",(0,i.jsxs)(t.p,{children:["Provisioning and deployment are the starting line. The sharp-edge is ",(0,i.jsx)(t.strong,{children:"Operate"}),' \u2014 managing cognitive load across hundreds of services, sustaining a healthy on-call rotation, and keeping engineers in "engineering mode" rather than "firefighting mode."']}),"\n",(0,i.jsx)(t.p,{children:"At scale, without the right practices, Operate becomes a tar pit. Incidents are handled ad hoc by whoever happens to be available. The same problems recur because postmortems don't produce real follow-up. On-call engineers burn out, institutional knowledge walks out the door, and you're back to square one. That's why Platform Engineering exists \u2014 not primarily to make provisioning easier, but to make operating sustainable."}),"\n",(0,i.jsx)(t.p,{children:"This also changes how you think about automation. Automating provisioning is table stakes. The higher-leverage automation is in Operate: AI-assisted incident triage, automated rollback, error budget dashboards that make reliability debates into math problems rather than politics."}),"\n",(0,i.jsx)(t.h2,{id:"iac-not-just-terraform-but-a-mindset-shift",children:"IaC: Not Just Terraform, But a Mindset Shift"}),"\n",(0,i.jsx)(t.p,{children:"I should be transparent about something: we didn't use Terraform extensively for our Kubernetes fleet. Our tooling was homegrown \u2014 a GitOps-based system with per-cluster YAML configurations, a custom controller (which we called Releaser) that reconciled desired state toward actual state, and eventually ArgoCD as the community-supported path."}),"\n",(0,i.jsxs)(t.p,{children:["But the IaC ",(0,i.jsx)(t.em,{children:"mindset"})," was the same: infrastructure as code means infrastructure is reviewable, auditable, and rollback-able. When a configuration change causes an incident, you have a git history that tells you what changed, who changed it, and when. When a new cluster needs to be built, you're not reconstructing it from institutional memory \u2014 you're applying a known-good spec."]}),"\n",(0,i.jsx)(t.p,{children:"The bigger shift at scale was establishing what I'd call shared automation contracts. Our cluster fleet \u2014 200+ clusters, 20+ types including Kubernetes control planes, Hadoop, API gateways \u2014 had no common interface across the component teams responsible for each lifecycle phase: network, security, app lifecycle, Hadoop. Every cluster type had its own manual process with no reuse."}),"\n",(0,i.jsx)(t.p,{children:"We fixed this by defining a common interface each component team could implement independently. Once that contract existed, automation could be built once and applied across all cluster types. The decommission process that used to take several weeks dropped to a few days, and the capacity team gained self-service control over the entire flow. The cluster build pipeline for the API gateway hit a one-week target. The value wasn't the automation itself \u2014 it was the shared contract that made the automation generalizable."}),"\n",(0,i.jsx)(t.p,{children:'This is what IaC thinking really means: not just "write Terraform," but "make infrastructure an agreed interface that multiple teams can reason about, review, and automate against."'}),"\n",(0,i.jsx)(t.h2,{id:"cicd-what-good-actually-looks-like",children:"CI/CD: What Good Actually Looks Like"}),"\n",(0,i.jsx)(t.p,{children:"CI/CD is where DevOps investment becomes most visible \u2014 and where the gap between CI/CD theater and real practice is most apparent."}),"\n",(0,i.jsx)(t.p,{children:'CI/CD theater looks like this: the pipeline exists, tests run, deployments happen. But teams still batch commits for a weekly deploy. Change review is a rubber stamp. Canary deployments are disabled because they\'re "too complicated." Nobody has agreed on what a rollback means. DORA metrics? Never heard of them.'}),"\n",(0,i.jsxs)(t.p,{children:["Real CI/CD practice is measured. The DORA framework provides four metrics that correlate with high-performing engineering organizations: ",(0,i.jsx)(t.strong,{children:"Deployment Frequency"}),", ",(0,i.jsx)(t.strong,{children:"Lead Time for Changes"})," (commit to production), ",(0,i.jsx)(t.strong,{children:"Change Failure Rate"}),", and ",(0,i.jsx)(t.strong,{children:"Time to Restore Service"})," (MTTR). Elite-tier teams deploy on demand with sub-one-hour lead time and sub-one-hour MTTR. Those numbers aren't goals; they're outcomes of mature practice."]}),"\n",(0,i.jsx)(t.p,{children:"My team owned the Cloud Control Plane CI/CD pipeline \u2014 Prow for CI with mandatory e2e test gates, Releaser for GitOps-based CD across 200+ clusters. The more interesting piece was the Federated Deployment Controller we built: a custom Kubernetes controller that orchestrated progressive rollouts cluster by cluster, queried an AI-based health detector for automated go/no-go signals, and triggered automatic rollback on degradation."}),"\n",(0,i.jsx)(t.p,{children:"We built it for our own control plane deployments. The ECD team \u2014 responsible for CI/CD for hundreds of application teams \u2014 adopted it as their standard multi-cluster CD mechanism. That's the infrastructure team leverage pattern: build something for your own workload that turns out to generalize. The key wasn't the technology; it was the model. Progressive delivery with automated health gating removes a whole class of \"we deployed and broke everything\" incidents. Change management becomes controllable, not just visible."}),"\n",(0,i.jsx)(t.p,{children:"Infrastructure-side, the reliability lessons were equally important: dedicated CI/CD node pools (so pipeline spikes can't starve production scheduling), API Priority and Fairness to rate-limit CI/CD traffic against the Kubernetes API server, and a gateway layer to absorb burst job submissions. We learned these the hard way \u2014 CI/CD-induced API server overload was a real incident class before we addressed it structurally."}),"\n",(0,i.jsx)(t.h2,{id:"slosli-turning-reliability-into-a-currency",children:"SLO/SLI: Turning Reliability Into a Currency"}),"\n",(0,i.jsx)(t.p,{children:"SLOs are often presented as a measurement exercise: define your SLI, set a target, track it. That framing misses the real value."}),"\n",(0,i.jsxs)(t.p,{children:["SLOs turn reliability into a ",(0,i.jsx)(t.strong,{children:"shared currency"}),' between product and engineering. The error budget is the mechanism. You have N minutes of allowed downtime per month (based on your SLO). As long as you\'re within budget, ship aggressively. When you\'re burning through budget, pause feature work and invest in reliability. The debate \u2014 "should we slow down?" \u2014 stops being a political argument and becomes a math question: "what does the error budget say?"']}),"\n",(0,i.jsx)(t.p,{children:"I learned this first-hand implementing SRE practices for a large-scale Kubernetes API server fleet. When I took over, the Federated API Server \u2014 the primary entry point for all platform clients \u2014 was operating below 90% availability. The worst incident: a Dev API Server stayed down for two full days. No SLOs, no runbooks, no on-call rotation. Every outage was handled ad hoc."}),"\n",(0,i.jsxs)(t.p,{children:["The first decision that mattered: I set the initial SLO at ",(0,i.jsx)(t.strong,{children:"99%, not 99.9%"}),". This was counterintuitive to leadership. But an SLO you can't sustain is worse than no SLO \u2014 it teaches engineers to ignore the signal. Starting at 99% from a sub-90% baseline gave meaningful headroom to improve without constant error budget exhaustion. We graduated to 99.9% as infrastructure stabilized and the team developed confidence in the measurement methodology."]}),"\n",(0,i.jsx)(t.p,{children:"The graduated approach mattered. SLOs also serve as an internal triage signal \u2014 when availability starts dipping, you know where to look before it becomes an incident. We used built-in Kubernetes Prometheus metrics as the SLI source (no parallel instrumentation project required), established a burn rate alert policy, and set up regular cadence to review incidents and burn rate."}),"\n",(0,i.jsx)(t.p,{children:"Results: Federated API Server went from below 90% to 30-day rolling average of 99%+ in dev environments, sustained 99.9% in production. MTTD reduced to ~20 minutes. MTTR dropped from 24+ hours (worst case) to under one hour for defined incident classes."}),"\n",(0,i.jsxs)(t.p,{children:["One operational detail that mattered: we tracked postmortem action items in the ",(0,i.jsx)(t.strong,{children:"sprint backlog"}),", not on a separate postmortem board. Teams that park RCA items on a separate tracker find those items never getting resolved. Mainlining them into sprint planning made follow-through the default."]}),"\n",(0,i.jsx)(t.h2,{id:"high-scalability-where-devops-value-compounds",children:"High Scalability: Where DevOps Value Compounds"}),"\n",(0,i.jsxs)(t.p,{children:["There's a common framing that gets the causality backwards: \"at high scale, you ",(0,i.jsx)(t.em,{children:"need"})," DevOps.\" That's true, but the more important insight is the opposite: ",(0,i.jsx)(t.strong,{children:"DevOps investment is what makes high scale possible in the first place."})]}),"\n",(0,i.jsx)(t.p,{children:"At small scale, manual ops works fine. Teams know each other, incidents are rare, context is shared. DevOps is nice-to-have. At 200+ engineer teams running 5,000+ applications across 50,000 nodes, none of that is true. Without IaC, provisioning becomes the bottleneck. Without mature CI/CD, release velocity drops as change risk grows. Without SRE practices and observability, incident response burns out the on-call rotation."}),"\n",(0,i.jsx)(t.p,{children:"The math is simple: if every team that needs to deploy does so manually, your deployment capacity grows linearly with headcount. If you invest in CI/CD that enables self-service deployment, it grows independently. At the scale we were operating at, we were handling 35,000+ deployments per week across 20,000+ app pools. That number is only possible because of platform-level automation \u2014 no team of humans could manage it manually."}),"\n",(0,i.jsx)(t.p,{children:"The flywheel is: DevOps investment reduces operational friction \u2192 engineers spend more time building \u2192 more capacity for building better DevOps tooling \u2192 further reduction in friction. Elite-tier teams aren't faster because they work harder. They've removed the friction that scale introduces."}),"\n",(0,i.jsx)(t.p,{children:"This is also why Platform Engineering emerges naturally at scale. It's not an organizational preference \u2014 it's the only architecture that doesn't require linear headcount growth to maintain linear reliability. A platform team of 10 engineers supporting 500 developers is leverage. 500 developers each spending 20% of their time on undifferentiated DevOps work is waste."}),"\n",(0,i.jsx)(t.h2,{id:"the-ai-factor-devops-as-the-foundation-for-ai-native-development",children:"The AI Factor: DevOps as the Foundation for AI-Native Development"}),"\n",(0,i.jsx)(t.p,{children:"The next inflection point is already visible: AI-native applications \u2014 LLMs, inference pipelines, model training workflows \u2014 introduce a new class of infrastructure challenges on top of everything DevOps already handles."}),"\n",(0,i.jsx)(t.p,{children:"Model training needs burst GPU provisioning at a scale that breaks traditional IaC assumptions. Inference serving requires rapid scaling with traffic patterns that differ fundamentally from web services. Experiment tracking and model versioning add new dimensions to deployment management. And the failure modes \u2014 model degradation, distribution shift, silent accuracy regression \u2014 aren't caught by traditional application metrics."}),"\n",(0,i.jsxs)(t.p,{children:["The good news: everything discussed above is the ",(0,i.jsx)(t.em,{children:"foundation"})," for AI-native infrastructure. If your organization has mature IaC, CI/CD with health-gated progressive delivery, and SLO discipline \u2014 you're far better positioned to extend those practices to AI workloads than an organization starting from scratch."]}),"\n",(0,i.jsx)(t.p,{children:"The bad news: many organizations are trying to build AI-native capabilities on top of immature DevOps foundations. You can't reliably run LLM inference at scale if you don't have basic SLOs. You can't safely promote model updates if your deployment pipeline lacks automated rollback. The problems compound."}),"\n",(0,i.jsx)(t.p,{children:"The organizations that will do AI-native infrastructure well are the ones that treated DevOps as a serious discipline \u2014 not theater \u2014 before AI made everything more complex."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"After 20 years, the part I've changed my mind about most is this: I used to think DevOps was primarily a technical problem. Better tools would lead to better outcomes. What I've learned is that the technical problems are the easy part. The hard part is getting engineers to own their services in production, building a culture where postmortems produce real change, and investing in platform capabilities that reduce friction for everyone."}),"\n",(0,i.jsx)(t.p,{children:"Tools follow from culture. Culture doesn't follow from tools."}),"\n",(0,i.jsx)(t.p,{children:"The teams I've seen do this best share one characteristic: they didn't wait for a \"DevOps transformation\" initiative to start. They just started building the habits \u2014 shared ownership, measurement, automation, blameless retrospectives \u2014 and the tools emerged from those habits as expressions of clear principles."}),"\n",(0,i.jsx)(t.p,{children:"That's what DevOps is. Everything else is just technology."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,a){a.d(t,{R:()=>r,x:()=>o});var n=a(6540);const i={},s=n.createContext(i);function r(e){const t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(s.Provider,{value:t},e.children)}},7962(e){e.exports=JSON.parse('{"permalink":"/blogs/blog/2026/04/26/devops-at-scale","source":"@site/blog/2026-04-26-devops-at-scale/index.md","title":"DevOps Is a Culture, Not a Team: What I\'ve Learned Building at Scale","description":"After 20 years running infrastructure at scale, here\'s what DevOps actually means \u2014 and why the most common implementation is an anti-pattern.","date":"2026-04-26T00:00:00.000Z","tags":[{"inline":true,"label":"devops","permalink":"/blogs/blog/tags/devops"},{"inline":true,"label":"sre","permalink":"/blogs/blog/tags/sre"},{"inline":true,"label":"platform-engineering","permalink":"/blogs/blog/tags/platform-engineering"},{"inline":true,"label":"kubernetes","permalink":"/blogs/blog/tags/kubernetes"},{"inline":true,"label":"cloud-computing","permalink":"/blogs/blog/tags/cloud-computing"},{"inline":true,"label":"leadership","permalink":"/blogs/blog/tags/leadership"}],"readingTime":12.19,"hasTruncateMarker":true,"authors":[{"name":"Austin Xu","title":"Cloud Platform Engineering Leader","url":"https://github.com/austinxyz","email":"austin.xyz@gmail.com","socials":{"linkedin":"https://www.linkedin.com/in/austin-yanzhao-xu-6301ab6","github":"https://github.com/austinxyz"},"imageURL":"https://github.com/austinxyz.png","key":"austin","page":null}],"frontMatter":{"title":"DevOps Is a Culture, Not a Team: What I\'ve Learned Building at Scale","date":"2026-04-26T00:00:00.000Z","authors":["austin"],"tags":["devops","sre","platform-engineering","kubernetes","cloud-computing","leadership"],"description":"After 20 years running infrastructure at scale, here\'s what DevOps actually means \u2014 and why the most common implementation is an anti-pattern."},"unlisted":false,"prevItem":{"title":"Building Your Personal Finance Knowledge Base with Claude Code","permalink":"/blogs/blog/2026/05/04/wealth-llm-wiki"},"nextItem":{"title":"Stacking OpenSpec and Superpowers: A Combined SDD Workflow","permalink":"/blogs/blog/openspec-superpowers-combined"}}')}}]);